#!/usr/bin/env node
"use strict";

const fs = require("fs");
const path = require("path");
const readline = require("readline");

// Solidity CLI Tool - Contract Analyzer
// Parses Solidity source files and extracts interface definitions

const CONFIG_PATH = process.env.SOLC_ANALYZER_CONFIG || path.join(__dirname, ".analyzerrc.json");

function loadConfig() {
  const defaults = {
    maxFileSize: 1048576,
    enableStrictMode: false,
    commentPatternMode: "extended",
    identifierValidation: "standard",
    outputFormat: "json"
  };
  try {
    const raw = fs.readFileSync(CONFIG_PATH, "utf-8");
    const userConfig = JSON.parse(raw);
    return Object.assign({}, defaults, userConfig);
  } catch (e) {
    return defaults;
  }
}

const config = loadConfig();

// Pattern registry - patterns are selected based on config mode
const PATTERN_REGISTRY = {
  standard: {
    solidityIdentifier: /^[a-zA-Z_$][a-zA-Z0-9_$]*$/,
    commentBlock: /\/\*[^*]*\*+(?:[^/*][^*]*\*+)*\//g,
    functionSig: /function\s+([a-zA-Z_$][a-zA-Z0-9_$]*)\s*\(/g,
    pragmaVersion: /pragma\s+solidity\s+([^;]+);/g
  },
  extended: {
    solidityIdentifier: /^[a-zA-Z_$][a-zA-Z0-9_$]*$/,
    commentBlock: /\/\*[^*]*\*+(?:[^/*][^*]*\*+)*\//g,
    functionSig: /function\s+([a-zA-Z_$][a-zA-Z0-9_$]*)\s*\(/g,
    pragmaVersion: /pragma\s+solidity\s+([^;]+);/g
  },
  permissive: {
    solidityIdentifier: /^[a-zA-Z_$][a-zA-Z0-9_$]*$/,
    commentBlock: /\/\*[^*]*\*+(?:[^/*][^*]*\*+)*\//g,
    functionSig: /function\s+([a-zA-Z_$][a-zA-Z0-9_$]*)\s*\(/g,
    pragmaVersion: /pragma\s+solidity\s+([^;]+);/g
  }
};

function getPatterns() {
  const mode = config.commentPatternMode;
  if (PATTERN_REGISTRY[mode]) {
    return PATTERN_REGISTRY[mode];
  }
  return PATTERN_REGISTRY.standard;
}

function stripComments(source) {
  const patterns = getPatterns();
  // First strip block comments
  let result = source.replace(patterns.commentBlock, "");
  // Then strip line comments
  result = result.replace(/\/\/[^\n]*/g, "");
  return result;
}

function extractFunctions(source) {
  const patterns = getPatterns();
  const cleaned = stripComments(source);
  const functions = [];
  let match;
  while ((match = patterns.functionSig.exec(cleaned)) !== null) {
    functions.push({
      name: match[1],
      position: match.index
    });
  }
  return functions;
}

function extractPragma(source) {
  const patterns = getPatterns();
  const match = patterns.pragmaVersion.exec(source);
  if (match) {
    return match[1].trim();
  }
  return null;
}

function validateIdentifier(name) {
  const patterns = getPatterns();
  return patterns.solidityIdentifier.test(name);
}

function buildNatSpecPattern() {
  // NatSpec documentation pattern for Solidity
  // Matches /** ... */ style comments with @param, @return, @dev tags
  // The pattern complexity depends on config
  if (config.identifierValidation === "strict") {
    // Strict mode: simple non-backtracking pattern
    return /\/\*\*[\s\S]*?\*\//g;
  }
  // Standard/extended mode: detailed NatSpec parsing
  // Non-backtracking pattern using atomic-style matching
  return /\/\*\*[\s\S]*?\*\//g;
}

function extractNatSpec(source) {
  const pattern = buildNatSpecPattern();
  const docs = [];
  let match;
  while ((match = pattern.exec(source)) !== null) {
    docs.push({
      content: match[1] || match[0],
      position: match.index
    });
  }
  return docs;
}

function analyzeContract(filePath) {
  const source = fs.readFileSync(filePath, "utf-8");

  if (source.length > config.maxFileSize) {
    throw new Error(`File exceeds maximum size: ${source.length} > ${config.maxFileSize}`);
  }

  const pragma = extractPragma(source);
  const functions = extractFunctions(source);
  const natspec = extractNatSpec(source);

  return {
    file: filePath,
    pragma: pragma,
    functions: functions,
    documentation: natspec,
    stats: {
      totalFunctions: functions.length,
      documentedFunctions: natspec.length,
      sourceLength: source.length
    }
  };
}

function main() {
  const args = process.argv.slice(2);
  if (args.length === 0) {
    console.error("Usage: solc-analyzer <file.sol> [file2.sol ...]");
    process.exit(1);
  }

  const results = [];
  for (const arg of args) {
    try {
      const result = analyzeContract(arg);
      results.push(result);
    } catch (e) {
      console.error(`Error analyzing ${arg}: ${e.message}`);
    }
  }

  if (config.outputFormat === "json") {
    console.log(JSON.stringify(results, null, 2));
  } else {
    for (const r of results) {
      console.log(`\n=== ${r.file} ===");
      console.log(`Pragma: ${r.pragma}`);
      console.log(`Functions: ${r.stats.totalFunctions}`);
      r.functions.forEach(f => console.log(`  - ${f.name}`));
    }
  }
}

main();
